import { useActionState } from 'react';

async function subscribe(previousState, formData) {
  const email = formData.get('email');
  if (!email.includes('@')) {
    return { error: 'Enter a valid email address.' };
  }
  await fetch('/api/subscribe', { method: 'POST', body: formData });
  return { success: `Subscribed ${email}.` };
}

function Subscribe() {
  const [state, formAction, isPending] = useActionState(subscribe, {});

  return (
    <form action={formAction}>
      <input name="email" required />
      <button disabled={isPending}>{isPending ? 'Sending…' : 'Subscribe'}</button>
      {state.error && <p role="alert">{state.error}</p>}
      {state.success && <p>{state.success}</p>}
    </form>
  );
}
